import{$ as e,A as t,B as n,V as r}from"./chunks/framework.Civ1omIV.js";import"./chunks/assets.DDN5FH9A.js";var i=JSON.parse(`{"title":"Clash","titleTemplate":"Clash","description":"Import your own subscription and manage multiple protocols and network routes in one fully open-source app for iPhone and iPad.","frontmatter":{"layout":"doc","title":"Clash","titleTemplate":"Clash","description":"Import your own subscription and manage multiple protocols and network routes in one fully open-source app for iPhone and iPad.","keywords":["Clash iOS","Clash for iPhone","Clash for iPad","open-source proxy client","mihomo iOS","multi-protocol network utility"],"jsonLd":{"@context":"https://schema.org","@type":"SoftwareApplication","name":"Clash","description":"Import your own subscription and manage multiple protocols and network routes in one fully open-source app for iPhone and iPad.","applicationCategory":"UtilitiesApplication","operatingSystem":["iOS","iPadOS"],"url":"https://clash.md/","downloadUrl":"https://apps.apple.com/app/id6794257189","codeRepository":["https://github.com/TokenPLS/Hako-Client","https://github.com/TokenPLS/Hako"],"inLanguage":"en-US"},"sidebar":false,"aside":false,"outline":false,"pageClass":"clash-home"},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":1785318168000}`),a={name:`index.md`};function o(t,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[r(`<div class="clash-product-lockup"><img class="clash-app-icon" src="/clash.md/brand/clash-app-icon.svg" alt="Clash app icon"><div class="clash-product-identity"><h1>Clash</h1><p>Rule-based proxy utility · powered by Hako</p></div></div><p>Clash is back, and this time it is native.</p><p>Clash gives Apple users a polished, multi-protocol, fully open-source choice. Transparency matters for software that handles subscriptions, credentials, and device traffic: the code is open to everyone, its data handling can be examined, and the community can verify its security independently.</p><p>Clash is built to fill that gap. Import your existing subscription or server configuration, then test, choose, and connect—all in one app. Clash follows your rules to decide which connections go directly and which use a proxy, keeping the whole workflow in one place.</p><p>Clash supports 21 common outbound protocol families, giving you the freedom to choose your protocol, subscription, and server. Both the client and the Hako core are fully open source, so anyone can inspect, discuss, and independently audit them. Security becomes a verifiable property.</p><div class="home-download-row"><a class="home-download" href="https://apps.apple.com/app/id6794257189" target="_blank" rel="noopener noreferrer">Download on the App Store</a></div><div class="home-link-list"><a href="./guide/"><strong>Getting started</strong><span>Import and connect in three steps</span></a><a href="./hako"><strong>About Hako</strong><span>See the open-source core behind Clash</span></a><a href="./privacy"><strong>Privacy Policy</strong><span>Transparent data handling</span></a><a href="./terms"><strong>Terms of Use</strong><span>What to know before using Clash</span></a></div><h2 id="fully-open-source-and-open-to-community-audit" tabindex="-1">Fully open source and open to community audit <a class="header-anchor" href="#fully-open-source-and-open-to-community-audit" aria-label="Permalink to “Fully open source and open to community audit”">​</a></h2><div class="community-link-list"><a data-community="github" href="https://github.com/TokenPLS/Hako-Client">Clash client</a><a data-community="github" href="https://github.com/TokenPLS/Hako">Hako core</a><a data-community="telegram" href="https://t.me/clashbyhako">Official channel</a></div><p>Have an idea or want to contribute? Issues and pull requests are welcome, and the Telegram channel is open for release updates and community conversations.</p><h2 id="on-iphone-and-ipad" tabindex="-1">On iPhone and iPad <a class="header-anchor" href="#on-iphone-and-ipad" aria-label="Permalink to “On iPhone and iPad”">​</a></h2><div class="clash-screenshots"><figure class="clash-screenshot clash-screenshot--iphone"><img src="/clash.md/screenshots/iphone-home.webp" alt="Clash connected in Rule mode on iPhone"><figcaption>iPhone</figcaption></figure><figure class="clash-screenshot clash-screenshot--ipad"><img src="/clash.md/screenshots/ipad-home.webp" alt="Clash connected in Rule mode on iPad"><figcaption>iPad</figcaption></figure></div><h2 id="apple-platforms" tabindex="-1">Apple platforms <a class="header-anchor" href="#apple-platforms" aria-label="Permalink to “Apple platforms”">​</a></h2><table tabindex="0"><thead><tr><th>Platform</th><th>Status</th></tr></thead><tbody><tr><td>iPhone and iPad</td><td>Preparing for App Store</td></tr><tr><td>macOS</td><td>In development</td></tr><tr><td>tvOS</td><td>In development</td></tr></tbody></table>`,14)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};